 [(("माँ को (LPS राज्य)", "Mother (LPS states)"), ("ग्रामीण ₹1,400, शहरी ₹1,000", "Rural ₹1,400, urban ₹1,000")), (("माँ को (HPS राज्य)", "Mother (HPS states)"), ("ग्रामीण ₹700, शहरी ₹600", "Rural ₹700, urban ₹600")), (("आशा को", "ASHA"), ("ग्रामीण ₹600, शहरी ₹400 (रिपोर्टों के अनुसार)", "Rural ₹600, urban ₹400 (as per reports)")), (("शुरुआत", "Started"), ("12 अप्रैल 2005", "12 April 2005"))],
