B("central-nikshay-poshan-yojana", None, "swasthya", "🩺", "https://tbcindia.mohfw.gov.in/ni-kshay-poshan-yojana/",
 ("नि-क्षय पोषण योजना – TB मरीज़ों को ₹1,000 महीना", "Ni-kshay Poshan Yojana – ₹1,000 a Month for TB Patients"),
 ("टीबी के इलाज के दौरान पोषण के लिए हर मरीज़ को हर महीने ₹1,000 सीधे बैंक खाते में (रिपोर्टों के अनुसार)।", "₹1,000 a month straight into the bank account of every TB patient during treatment, for nutrition (as per reports)."),
 ("केंद्र · स्वास्थ्य", "Central · Health"), ("स्वास्थ्य मंत्रालय, भारत सरकार (राष्ट्रीय टीबी उन्मूलन कार्यक्रम)", "Ministry of Health, Government of India (National TB Elimination Programme)"),
 [(("राशि", "Amount"), ("₹1,000 प्रति माह (अक्टूबर 2024 से, पहले ₹500)", "₹1,000 a month (since Oct 2024, earlier ₹500)")), (("किसके लिए", "For"), ("नि-क्षय पोर्टल पर दर्ज टीबी मरीज़", "TB patients notified on the Ni-kshay portal")), (("भुगतान", "Payment"), ("DBT से बैंक खाते में", "By DBT into the bank account")), (("हेल्पलाइन", "Helpline"), ("1800-11-6666", "1800-11-6666"))],
 ("नि-क्षय पोषण योजना में टीबी का इलाज करा रहे मरीज़ को पोषण के लिए हर महीने सीधे बैंक खाते में पैसा मिलता है। डेक्कन हेराल्ड (अक्टूबर 2024) के अनुसार स्वास्थ्य मंत्री ने 7 अक्टूबर 2024 को राशि ₹500 से बढ़ाकर ₹1,000 प्रति माह कर दी। मरीज़ को खुद आवेदन नहीं करना पड़ता; इलाज करने वाला स्वास्थ्य केंद्र या अस्पताल मरीज़ को नि-क्षय पोर्टल पर दर्ज करता है।",
  "Under the Ni-kshay Poshan Yojana a patient being treated for TB gets money every month straight into the bank account for nutrition. As per Deccan Herald (Oct 2024) the Health Minister doubled the amount from ₹500 to ₹1,000 a month on 7 October 2024. The patient does not have to apply; the health centre or hospital that treats the patient enters them on the Ni-kshay portal."),
 [("₹1,000 प्रति माह पोषण सहायता (डेक्कन हेराल्ड और पॉलिसीबाज़ार के अनुसार)", "₹1,000 a month nutrition support (as per Deccan Herald and Policybazaar)"), ("रिपोर्टों के अनुसार दवा-संवेदी टीबी में छह महीने के इलाज पर लगभग ₹6,000, और दवा-प्रतिरोधी टीबी में पूरे इलाज के दौरान भुगतान", "As per reports about ₹6,000 over six months of treatment in drug-sensitive TB, and payment for the whole treatment in drug-resistant TB"), ("पैसा DBT से सीधे खाते में आता है, बिचौलिए की ज़रूरत नहीं", "Money comes by DBT straight into the account, no middleman needed"), ("रिपोर्टों के अनुसार कम वज़न (BMI 18.5 से कम) वाले मरीज़ों को शुरुआती दो महीने अतिरिक्त पोषण सामग्री भी दी जाती है", "As per reports patients with low weight (BMI under 18.5) also get extra nutrition supplements in the first two months")],
 [("कोई भी टीबी मरीज़ जिसे नि-क्षय पोर्टल पर दर्ज किया गया हो (सरकारी या निजी अस्पताल, दोनों में)", "Any TB patient notified on the Ni-kshay portal (in a government or a private hospital)"), ("पॉलिसीबाज़ार के अनुसार इसमें आय या जाति की कोई शर्त नहीं है", "As per Policybazaar there is no income or caste condition"), ("बैंक खाता आधार से जुड़ा होना चाहिए", "The bank account should be linked with Aadhaar")],
 [("जिनकी जाँच में टीबी की पुष्टि नहीं हुई या जिन्हें पोर्टल पर दर्ज नहीं किया गया", "Those whose TB was not confirmed or who were not entered on the portal")],
 [AADHAAR, ("आधार से जुड़ी बैंक पासबुक", "Aadhaar-linked bank passbook"), ("मोबाइल नंबर", "Mobile number")],
 [("सरकारी या मान्यता प्राप्त निजी अस्पताल/स्वास्थ्य केंद्र में जाँच और इलाज शुरू कराएँ", "Get tested and start treatment at a government or recognised private hospital/health centre"), ("स्वास्थ्य कर्मचारी आपको नि-क्षय पोर्टल पर दर्ज करेंगे; आधार और बैंक खाते की जानकारी दें", "The health worker will enter you on the Ni-kshay portal; give your Aadhaar and bank details"), ("बजाज फिनसर्व (जून 2026) के अनुसार जाँच के बाद ज़िला टीबी अधिकारी PFMS से भुगतान मंज़ूर करता है, जिसमें लगभग 7-10 कार्य-दिवस लग सकते हैं", "As per Bajaj Finserv (Jun 2026) the District TB Officer approves payment through PFMS after verification, which can take about 7-10 working days"), ("बैंक स्टेटमेंट में 'DBT' जैसी प्रविष्टि देखें; पैसा न आए तो अपने स्वास्थ्य केंद्र या ज़िला टीबी कार्यालय से पूछें", "Look for a 'DBT' type entry in the bank statement; if the money does not come, ask your health centre or District TB office")],
 ("tbcindia.mohfw.gov.in – राष्ट्रीय टीबी कार्यक्रम का आधिकारिक पन्ना", "tbcindia.mohfw.gov.in – official page of the national TB programme"),
 ("टीबी हेल्पलाइन: 1800-11-6666 (आधिकारिक पन्ने पर दिखी)", "TB helpline: 1800-11-6666 (seen on the official page)"),
 [(("पैसा कितना मिलता है?", "How much money is paid?"), ("रिपोर्टों के अनुसार ₹1,000 प्रति माह (अक्टूबर 2024 से)। एक साइट के भुगतान-स्थिति वाले हिस्से में अब भी ₹500 लिखा है, वह पुराना लगता है। आधिकारिक पन्ना राशि नहीं बताता, इसलिए स्वास्थ्य केंद्र से पूछ लें।", "As per reports ₹1,000 a month (since October 2024). One website still shows ₹500 in its payment-status section, which looks outdated. The official page does not state the amount, so confirm with the health centre.")), (("क्या आवेदन करना पड़ता है?", "Do I have to apply?"), ("नहीं, इलाज करने वाला केंद्र आपको पोर्टल पर दर्ज करता है। बस आधार और बैंक खाता सही रखें।", "No, the treating centre enters you on the portal. Just keep your Aadhaar and bank account correct.")), (("क्या परिवार के सदस्य के खाते में पैसा आ सकता है?", "Can the money go to a family member's account?"), ("स्रोत अलग-अलग कहते हैं (एक के अनुसार अभिभावक का खाता चल सकता है, दूसरे के अनुसार सिर्फ़ मरीज़ का), इसलिए अपने ज़िला टीबी कार्यालय से पूछें।", "Sources differ (one says a guardian's account can be used, another says only the patient's own), so ask your District TB office."))],
 ("स्रोत जाँचे (19 नवंबर 2026): टीबी कंट्रोल डिवीज़न का पन्ना (16 नवंबर 2026 को अपडेट), डेक्कन हेराल्ड (अक्टूबर 2024), पॉलिसीबाज़ार, बजाज फिनसर्व (6 जून 2026)। राशि आधिकारिक दिशानिर्देश PDF से मिलान नहीं की जा सकी। इलाज के लिए सिर्फ़ डॉक्टर की सलाह मानें; पैसे के बदले नाम जुड़वाने का दावा करने वालों से सावधान रहें।",
  "Sources checked (19 Nov 2026): TB Control Division page (updated 16 Nov 2026), Deccan Herald (Oct 2024), Policybazaar, Bajaj Finserv (6 Jun 2026). The amount could not be matched against the official guideline PDF. For treatment follow only your doctor's advice; beware of anyone who asks for money to add your name."))
